// Original teaching activities, aligned to AQA Chemistry 4.1 / Trilogy 5.1.
export const elements = [
 ['H','Hydrogen',1,1,1,1],['He','Helium',2,4,0,1],['Li','Lithium',3,7,1,2],['Be','Beryllium',4,9,2,2],['B','Boron',5,11,3,2],['C','Carbon',6,12,4,2],['N','Nitrogen',7,14,5,2],['O','Oxygen',8,16,6,2],['F','Fluorine',9,19,7,2],['Ne','Neon',10,20,0,2],['Na','Sodium',11,23,1,3],['Mg','Magnesium',12,24,2,3],['Al','Aluminium',13,27,3,3],['Si','Silicon',14,28,4,3],['P','Phosphorus',15,31,5,3],['S','Sulfur',16,32,6,3],['Cl','Chlorine',17,35,7,3],['Ar','Argon',18,40,0,3],['K','Potassium',19,39,1,4],['Ca','Calcium',20,40,2,4]
].map(([symbol,name,z,mass,group,period])=>({symbol,name,z,mass,group,period}));
export const question=(id,prompt,options,answer,why,concept)=>({id,prompt,options,answer,why,concept});
const Q=question;
const card=(title,text,scene='water')=>({title,text,scene});
export const lessons=[
{id:'particles',title:'Atoms, elements & compounds',short:'The building blocks',refs:['1.1.1'],minutes:15,widget:'molecules',big:'An element has one type of atom. A compound has different elements chemically joined in a fixed ratio.',learn:[
card('Start with the atom.','An atom is the smallest part of an element that can exist. Its symbol identifies the element: H is hydrogen, O is oxygen and Na is sodium. Elements are listed in the periodic table. Use the element explorer later in this topic to learn the first 20 symbols.','oxygen'),
card('Molecules can be elements.','O₂ has two oxygen atoms chemically joined. It is a molecule of an element. H₂O has hydrogen and oxygen in a fixed 2:1 ratio, so it is a compound. CO₂ has one carbon and two oxygen atoms. A small number belongs to the symbol immediately before it; no number means one.','water'),
card('Joining is different from mixing.','A mixture contains substances together without chemical bonds joining those substances to one another. Their chemical properties remain. A compound is a new substance, formed by a chemical reaction; separating it into elements needs chemical reactions. A reaction can transfer energy. Some compounds form extended lattices rather than separate molecules.','mixture')],
practice:[Q('p-o2','Classify O₂.',['A compound','A molecule of an element','A mixture'],1,'Both atoms are oxygen. A compound needs different elements.','elements'),Q('p-co2','How many atoms are in CO₂?',['2','3','4'],1,'One C plus two O gives three atoms.','formulae')],
check:[Q('c-p1','A sample contains only H₂O molecules. It is…',['An element','A compound','A mixture'],1,'Each molecule has two different elements chemically joined.','elements'),Q('c-p2','Which sample is a mixture?',['Only O₂ molecules','Only CO₂ molecules','Separate H₂ and O₂ molecules together'],2,'Two substances are together without being chemically joined to each other.','mixtures'),Q('c-p3','Which change can separate a compound into its elements?',['A suitable chemical reaction','Filtration','Sorting by particle size'],0,'Physical separation cannot break the chemical combination in a compound.','elements')],skills:['WS1.2','WS4.1','MS5b']},
{id:'equations',title:'Symbols, formulae & equations',short:'Read the reaction',refs:['1.1.1'],minutes:15,widget:'balance',big:'Balance equations by changing coefficients. Changing a subscript changes the substance.',learn:[
card('Translate symbols into substances.','H₂, O₂, N₂, F₂ and Cl₂ are diatomic elemental molecules. NaCl is sodium chloride; MgO is magnesium oxide; CO₂ is carbon dioxide. In a binary compound, the non-metal name usually ends in -ide. An -ate name usually signals an oxygen-containing group: calcium carbonate is CaCO₃. Use the given formula and familiar element names; do not guess an unfamiliar formula from a name.','carbon'),
card('New substances, same atoms.','A word equation names reactants on the left and products on the right: hydrogen + oxygen → water. A symbol equation uses formulae: 2H₂ + O₂ → 2H₂O. There are four H atoms and two O atoms on each side. The atoms are rearranged, not created or destroyed. Change the number of whole particles to balance; keep each formula intact.','water'),
card('Charges must balance too.','An ionic equation leaves out ions that do not change. For example, Ag⁺ + Cl⁻ → AgCl shows silver chloride forming; the total charge is zero on each side. A half-equation tracks electron transfer: Na → Na⁺ + e⁻. Electrons have a negative charge. Higher Tier students should practise balanced ionic and half-equations where relevant; these return in chemical changes.','oxygen')],
practice:[Q('p-e1','What is MgO called?',['Magnesium oxygen','Magnesium oxide','Magnesium carbonate'],1,'Oxygen becomes oxide in this binary compound.','formulae'),Q('p-e2','Balance: Mg + O₂ → MgO. Coefficients are…',['1, 1, 1','2, 1, 2','1, 2, 1'],1,'2Mg + O₂ → 2MgO has two Mg and two O atoms on each side.','equations'),Q('p-eht','Complete the half-equation Na → Na⁺ + …',['e⁻','H⁺','O²⁻'],0,'One electron is lost; +1 and −1 sum to zero on the right.','ionic-equations')],
check:[Q('c-e1','Which is balanced?',['H₂ + O₂ → H₂O','2H₂ + O₂ → 2H₂O','H₂ + 2O₂ → H₂O'],1,'The balanced equation contains four H atoms and two O atoms on each side.','equations'),Q('c-e2','Balance 2Na + Cl₂ → ? NaCl.',['1','2','4'],1,'Two sodium atoms and two chlorine atoms form two formula units of NaCl.','equations'),Q('c-e3','Why cannot H₂O be changed to H₂O₂ to balance an equation?',['It changes water into a different substance','Subscripts can never appear','It changes hydrogen into oxygen'],0,'Formulae identify substances. Hydrogen peroxide is not water.','equations')],higherQuestions:['p-eht'],skills:['WS4.1','MS3a']},
{id:'separation',title:'Mixtures & separation',short:'Separate without reacting',refs:['1.1.2'],minutes:18,widget:'separate',big:'Choose a physical separation method using solubility, boiling point or attraction to the stationary phase.',learn:[
card('Separate an insoluble solid.','Filter sand from water: sand stays on the filter paper as residue; water passes through as filtrate. Dissolved salt passes through too, so filtration cannot remove it. To collect crystals from salt solution, evaporate some water to concentrate the solution, cool it to crystallise, then filter and dry the crystals.','mixture'),
card('Collect a liquid.','Simple distillation recovers a solvent: heat the solution, then cool the vapour in a condenser and collect liquid distillate. Dissolved salt stays in the flask. Fractional distillation separates miscible liquids with different boiling points. Repeated evaporation and condensation in the fractionating column enrich the vapour in the lower-boiling liquid.','water'),
card('Follow the colours.','In paper chromatography, the solvent moves through the paper and dissolved substances travel different distances. Different attraction to the paper and solubility in the solvent produce separation. Draw a pencil baseline above the solvent level; ink would dissolve, and a submerged sample would wash off. A pure substance generally gives one spot in a suitable solvent; a mixture can give several.','mixture')],
practice:[Q('p-s1','Which method collects water from salt solution?',['Filtration','Simple distillation','Crystallisation'],1,'Evaporate water, then condense and collect its vapour.','separation'),Q('p-s2','Why use a pencil baseline in chromatography?',['Graphite does not dissolve and travel with this solvent','Pencil makes the solvent boil','Pencil separates the colours'],0,'A dissolving ink baseline would interfere with the chromatogram.','chromatography')],
check:[Q('c-s1','Collect sand from sand and water using…',['Filtration','Fractional distillation','Chromatography'],0,'Sand is insoluble and remains as residue.','separation'),Q('c-s2','Separate ethanol and water most suitably using…',['Filtration','Fractional distillation','A magnet'],1,'They are miscible liquids with different boiling points.','separation'),Q('c-s3','Why keep the chromatography sample above the solvent surface?',['So it is carried up the paper instead of washing into the reservoir','So it cannot dissolve at all','So the solvent cannot rise'],0,'The sample dissolves into the moving solvent on the paper.','chromatography')],skills:['WS2.2','WS2.3','AT4']},
{id:'models',title:'How atomic models changed',short:'Follow the evidence',refs:['1.1.3'],minutes:15,widget:'scatter',big:'A scientific model changes when new evidence cannot be explained by the old model.',learn:[
card('An atom with an inside.','Early models treated atoms as tiny indivisible spheres. Discovering the negatively charged electron showed that atoms had smaller parts. In the plum pudding model, electrons were embedded in a spread-out ball of positive charge. The atom was neutral overall.','oxygen'),
card('A small target, a big surprise.','In alpha-particle scattering, most positively charged alpha particles went straight through thin metal foil. Some were deflected and very few turned back. This suggested mostly empty space with a tiny, dense, positively charged nucleus containing most of the mass. A diffuse positive ball could not explain the large deflections.','oxygen'),
card('Refining the nuclear model.','Bohr proposed electrons at particular distances from the nucleus, in energy levels. Calculations agreed with observations. Later work identified protons within the nucleus. Chadwick supplied evidence for neutrons, about 20 years after the nuclear model was accepted. Models can be useful yet incomplete; independent checking and peer review help scientists evaluate evidence.','oxygen')],
practice:[Q('p-m1','Most alpha particles passed straight through. This suggests…',['Atoms are mostly empty space','Atoms are completely solid','Every particle hits a nucleus'],0,'A very small nucleus occupies little of the atom’s volume.','atomic-evidence'),Q('p-m2','Large deflections are evidence for…',['A tiny concentrated positive nucleus','Positive charge spread evenly throughout the atom','No positive charge'],0,'A concentrated positive charge strongly repels nearby alpha particles.','atomic-evidence')],
check:[Q('c-m1','Which discovery prompted the plum pudding model?',['The electron','The neutron','The whole nucleus'],0,'The electron showed that an atom was divisible.','atomic-evidence'),Q('c-m2','Bohr added which idea?',['Electrons in specific energy levels','Neutrons embedded outside the atom','Atoms with no nucleus'],0,'Electrons occupy permitted energy levels.','atomic-evidence'),Q('c-m3','Why did scientists replace plum pudding?',['New scattering evidence contradicted it','Models change only because they get old','The model had no electrons'],0,'Unexpected large deflections required concentrated positive charge.','atomic-evidence')],skills:['WS1.1','WS1.2','WS1.6']},
{id:'subatomic',title:'Protons, neutrons & electrons',short:'Inside the atom',refs:['1.1.4','1.1.5'],minutes:15,widget:'atom',big:'Protons identify the element. Electrons determine charge. Almost all atomic mass is in the nucleus.',learn:[
card('Three particles, different roles.','A proton has relative charge +1 and relative mass 1. A neutron has charge 0 and relative mass 1. An electron has charge −1 and a very small mass, about 1/1836 of a proton. Protons and neutrons occupy the nucleus; electrons occupy energy levels around it.','atom:Na'),
card('Count the charge.','Atomic number is the proton count. Neutral atoms have equal protons and electrons. Losing electrons makes a positive ion; gaining electrons makes a negative ion. Sodium has 11 protons: Na has 11 electrons, while Na⁺ has 10. Changing proton count changes the element.','atom:Na'),
card('A matter of scale.','A typical atomic radius is about 0.1 nm, or 1 × 10⁻¹⁰ m. A nucleus has a radius around 10⁻¹⁴ m, roughly ten thousand times smaller or less. Almost all mass is in this tiny nucleus. If an atom were represented by a radius of 100 m, a nucleus on the 1:10,000 scale would have a radius of 1 cm. Our model exaggerates the nucleus so you can see it.','atom:He')],
practice:[Q('p-a1','A particle has 12 protons and 10 electrons. Its charge is…',['2+','2−','0'],0,'+12 plus −10 is +2.','ions'),Q('p-a2','Which particle has no charge?',['Proton','Electron','Neutron'],2,'Neutrons are neutral.','subatomic')],
check:[Q('c-a1','A neutral magnesium atom has atomic number 12. Electrons?',['10','12','24'],1,'Neutral atoms have equal proton and electron counts.','subatomic'),Q('c-a2','Which change makes a negative ion?',['Gaining electrons','Losing electrons','Gaining protons'],0,'Extra negatively charged electrons make a negative ion.','ions'),Q('c-a3','0.1 nm in metres is…',['1 × 10⁻¹⁰ m','1 × 10⁻⁹ m','1 × 10¹⁰ m'],0,'Nano means 10⁻⁹; 0.1 × 10⁻⁹ = 10⁻¹⁰.','scale')],skills:['WS1.2','WS4.3','WS4.4','MS1b','MS1d']},
{id:'isotopes',title:'Isotopes & relative atomic mass',short:'Same element, different mass',refs:['1.1.5','1.1.6'],minutes:18,widget:'isotopes',big:'Isotopes share a proton count, but differ in neutron count. Relative atomic mass is an abundance-weighted average.',learn:[
card('Read the two numbers.','In isotope notation, the mass number A is written above the atomic number Z, to the left of the symbol. A = protons + neutrons. Z = protons. Therefore neutrons = A − Z. Carbon-12 and carbon-14 both have six protons, but have six and eight neutrons respectively.','atom:C'),
card('The charge is a separate clue.','Isotopes differ in neutrons, not protons. An ion differs from its neutral atom in electron count. A chlorine-37 ion, Cl⁻, has 17 protons, 20 neutrons and 18 electrons: calculate neutrons from 37 − 17, then account for the extra electron. Mass number is a whole-number particle count, not an element’s average mass.','atom:Cl'),
card('Calculate the average.','For a sample containing 75% chlorine-35 and 25% chlorine-37: relative atomic mass = (35 × 75 + 37 × 25) ÷ 100 = 35.5. Abundance matters: the answer lies closer to 35 because that isotope is more common. Relative atomic mass has no unit. These abundances are a simplified example, not a claim about every chlorine sample.','atom:Cl')],
practice:[Q('p-i1','Carbon-14 has atomic number 6. Neutrons?',['6','8','14'],1,'14 − 6 = 8.','isotopes'),Q('p-i2','What changes between isotopes of one element?',['Proton count','Neutron count','The element symbol'],1,'Proton number stays fixed, so the element stays the same.','isotopes')],
check:[Q('c-i1','²³Na⁺ has Z = 11. Its p, n, e counts are…',['11, 12, 10','11, 11, 12','12, 11, 10'],0,'Protons = 11; neutrons = 23 − 11 = 12; one electron lost leaves 10.','isotopes'),Q('c-i2','An element is 50% mass-10 and 50% mass-11. Relative atomic mass?',['10','10.5','11'],1,'(10 × 50 + 11 × 50) ÷ 100 = 10.5.','weighted-mass'),Q('c-i3','An element is 80% mass-20 and 20% mass-22. Relative atomic mass?',['20.4','21','21.6'],0,'(20 × 80 + 22 × 20) ÷ 100 = 20.4.','weighted-mass')],skills:['MS1c','MS3c','WS1.2']},
{id:'electrons',title:'Electron arrangements',short:'Fill the energy levels',refs:['1.1.7'],minutes:15,widget:'shells',big:'For the first 20 elements, fill the lowest available shells: 2, then 8, then 8, then 2.',learn:[
card('Fill from the inside.','Electrons occupy the lowest available energy levels first. For the first 20 neutral atoms, use shell capacities of 2, 8, 8, then 2. This is a GCSE model for these elements, not a universal rule for all atoms. Hydrogen is 1; helium is 2; carbon is 2,4; neon is 2,8.','atom:Ne'),
card('Connect a number to a diagram.','Sodium has 11 electrons: 2,8,1. Chlorine has 17: 2,8,7. Calcium has 20: 2,8,8,2. Every number counts electrons in one occupied shell. The total must match atomic number for a neutral atom. Represent arrangements as either a shell diagram or a number list.','atom:Na'),
card('The outside matters.','Outer electrons help explain reactions. Sodium can lose its one outer electron to form Na⁺, with arrangement 2,8. Chlorine can gain one to form Cl⁻, with arrangement 2,8,8. The nucleus stays the same during this electron transfer.','atom:Cl')],
practice:[Q('p-el1','Which is aluminium, Z = 13?',['2,8,3','2,3,8','2,8,8'],0,'Fill the inner shell, then the second, leaving three.','shells'),Q('p-el2','Calcium has arrangement…',['2,8,10','2,8,8,2','2,8,2'],1,'Twenty electrons occupy four shells in this GCSE model.','shells')],
check:[Q('c-el1','A neutral atom is 2,8,6. Atomic number?',['6','14','16'],2,'2 + 8 + 6 = 16 electrons, so 16 protons.','shells'),Q('c-el2','Which arrangement is magnesium, Z = 12?',['2,8,2','2,2,8','2,10'],0,'The first two shells fill before the remaining two enter the third.','shells'),Q('c-el3','What is the arrangement of Na⁺?',['2,8','2,8,1','2,8,2'],0,'Sodium loses its outer electron, leaving ten electrons.','ions')],skills:['WS1.2','MS5b']},
{id:'periodic',title:'The periodic table',short:'Find the pattern',refs:['1.2.1','1.2.2'],minutes:18,widget:'periodic',big:'Atomic number orders the modern table. Electron arrangements explain its repeating chemical patterns.',learn:[
card('Rows and columns mean something.','The modern table runs in increasing atomic number. Rows are periods; columns are groups. For the main groups studied here, group number gives outer electrons, except Group 0 which has a full outer shell. Period number gives occupied shells. Sodium (2,8,1) is in Period 3, Group 1; chlorine (2,8,7) is in Period 3, Group 7.','atom:Na'),
card('Learn the first 20.','Explore H hydrogen, He helium, Li lithium, Be beryllium, B boron, C carbon, N nitrogen, O oxygen, F fluorine, Ne neon, Na sodium, Mg magnesium, Al aluminium, Si silicon, P phosphorus, S sulfur, Cl chlorine, Ar argon, K potassium and Ca calcium. Use the supplied periodic table to link symbols, names and proton numbers.','atom:Ca'),
card('A prediction that paid off.','Early tables followed atomic weight and sometimes put chemically different elements together. Mendeleev left gaps for undiscovered elements and sometimes changed weight order to keep similar properties together. Later discoveries matched predictions, supporting the pattern. Isotopes explain why ordering by average mass can differ from ordering by proton number: the modern table uses atomic number.','atom:Ar')],
practice:[Q('p-t1','An atom is 2,8,7. Its group and period are…',['Group 7, Period 3','Group 3, Period 7','Group 0, Period 3'],0,'Seven outer electrons; three occupied shells.','periodic-patterns'),Q('p-t2','Why did Mendeleev leave gaps?',['To predict undiscovered elements with suitable properties','To remove all metals','To avoid any predictions'],0,'Discoveries fitting his predictions supported his table.','table-history')],
check:[Q('c-t1','The modern periodic table is ordered by…',['Atomic number','Alphabetical name','Neutron number'],0,'Atomic number is the number of protons.','periodic-patterns'),Q('c-t2','Which symbol represents potassium?',['P','K','Po'],1,'Potassium is K; P is phosphorus.','symbols'),Q('c-t3','An element in Group 1, Period 3 has arrangement…',['2,8,1','2,1','2,8,7'],0,'Three shells and one outer electron.','periodic-patterns')],skills:['WS1.1','WS1.2','WS1.6']},
{id:'metals',title:'Metals & non-metals',short:'Predict from position',refs:['1.2.3'],minutes:12,widget:'metals',big:'Metals generally lose electrons to form positive ions. Non-metals do not form positive ions in these GCSE reactions.',learn:[
card('Locate the elements.','Most elements are metals. They occupy the left and central regions of the periodic table; non-metals are mainly towards the top right. Hydrogen is a non-metal even though it is shown above Group 1. The boundary is not a rule that every element on one side behaves identically.','atom:Mg'),
card('Compare the properties.','Metals generally conduct electricity and heat, are shiny when freshly cut or polished, and can be bent or shaped. Many have high melting points. Non-metals are often poor conductors and, when solid, brittle. There are exceptions: graphite conducts electricity and mercury is liquid near room temperature. Use evidence about a particular sample.','atom:C'),
card('Explain the chemistry.','Metals tend to lose outer electrons, forming positive ions: Mg → Mg²⁺ + 2e⁻. Non-metals may gain electrons or share electrons in bonds. Their position and outer-electron arrangement help explain these reactions. Losing an electron changes charge, not the identity of the element.','atom:Mg')],
practice:[Q('p-me1','Which is a metal?',['Magnesium','Chlorine','Oxygen'],0,'Magnesium lies in Group 2 on the left of the table.','metals'),Q('p-me2','What happens when a metal forms a positive ion?',['It loses electrons','It gains electrons','It loses its nucleus'],0,'Removing negative charge leaves a positive ion.','ions')],
check:[Q('c-me1','A material conducts electricity and can be hammered into shape. It is likely…',['A metal','A noble gas','An insulating non-metal'],0,'These are characteristic metallic properties.','metals'),Q('c-me2','Why does Mg²⁺ still count as magnesium?',['Its proton number is unchanged','It has gained two protons','Its electrons identify the element'],0,'Proton number determines the element.','ions'),Q('c-me3','Which statement is most accurate?',['Every non-metal is an electrical insulator','Non-metals are generally poor conductors, with exceptions','Every metal is solid at room temperature'],1,'Graphite is one conducting non-metal; mercury is a liquid metal.','metals')],skills:['WS1.2','WS3.5']},
{id:'noble',title:'Group 0: noble gases',short:'A full outer shell',refs:['1.2.4'],minutes:12,widget:'noble',big:'A stable, full outer shell makes noble gases unreactive. Their boiling points rise down the group.',learn:[
card('Stable arrangements.','Helium (He), neon (Ne), argon (Ar), krypton (Kr), xenon (Xe) and radon (Rn) belong to Group 0, also called the noble gases. They are very unreactive because their electron arrangements are stable. They normally exist as separate atoms rather than molecules. Helium has a full first shell with two electrons; the other noble gases have eight outer electrons.','atom:He'),
card('One group, a physical trend.','Boiling points increase down Group 0 as relative atomic mass increases. Helium boils at about −269 °C, neon at −246 °C and argon at −186 °C. A less negative temperature is higher: −186 °C is higher than −246 °C. All three are gases at room temperature.','atom:Ar'),
card('Predict carefully.','Use a trend to make a prediction, rather than treating all properties as identical. Krypton is below argon, so its boiling point should be higher. A stable outer shell explains low chemical reactivity; it does not mean the substances have the same boiling point.','atom:Ne')],
practice:[Q('p-n1','Why is helium stable with only two electrons?',['Its first shell is full','Every shell must contain eight','It has no protons'],0,'The first shell can hold two electrons.','group0'),Q('p-n2','Which temperature is higher?',['−246 °C','−186 °C','They are equal'],1,'−186 °C is closer to zero, so it is higher.','group0')],
check:[Q('c-n1','Noble gases are unreactive mainly because…',['Their outer shell is full','They have no electrons','They are all heavy'],0,'Their stable electron arrangements make electron gain/loss unlikely.','group0'),Q('c-n2','Going down Group 0, boiling points…',['Increase','Decrease','Stay identical'],0,'The observed boiling-point trend is upward.','group0'),Q('c-n3','Neon normally exists as…',['Separate atoms','Ne₂ molecules','A giant metallic lattice'],0,'Noble gases do not readily form molecules.','group0')],skills:['WS1.2','MS4a']},
{id:'alkali',title:'Group 1: alkali metals',short:'One electron to lose',refs:['1.2.5'],minutes:18,widget:'alkali',big:'Group 1 metals have one outer electron. Reactivity increases down the group.',learn:[
card('Meet the family.','Lithium, sodium and potassium are the first three alkali metals. Rubidium (Rb), caesium (Cs) and francium (Fr) are also in Group 1. Each has one outer electron and forms a +1 ion by losing it. The first three are soft metals, have relatively low densities and react readily. Hydrogen is not an alkali metal.','atom:Li'),
card('Reactions make new substances.','With water: metal + water → metal hydroxide + hydrogen. For sodium: 2Na + 2H₂O → 2NaOH + H₂. The hydroxide solution is alkaline. With chlorine, each makes a metal chloride: 2Li + Cl₂ → 2LiCl. With oxygen they form oxides; one example is 4Li + O₂ → 2Li₂O. Lithium, sodium and potassium share these reaction patterns.','atom:Na'),
card('Explain the trend.','Going down Group 1, extra occupied shells place the outer electron farther from the nucleus and increase shielding by inner electrons. The outer electron is lost more easily, so reactivity increases: lithium < sodium < potassium. These reactions can be hazardous; this lesson uses a symbolic simulation rather than instructions for doing them at home.','atom:K')],
practice:[Q('p-g1','Which is most reactive: Li, Na or K?',['Lithium','Sodium','Potassium'],2,'The outer electron is lost more easily farther down Group 1.','group1'),Q('p-g2','Sodium and water produce…',['Sodium hydroxide and hydrogen','Sodium chloride and oxygen','Only sodium oxide'],0,'Metal + water → metal hydroxide + hydrogen.','group1-reactions')],
check:[Q('c-g1','Why does potassium react more readily than lithium?',['More shielding and a more distant outer electron','It has no nucleus','It has seven outer electrons'],0,'The outer electron is less strongly attracted and easier to lose.','group1'),Q('c-g2','Lithium reacts with chlorine to make…',['Lithium chloride','Lithium hydroxide','Lithium carbonate'],0,'Metal + chlorine → metal chloride.','group1-reactions'),Q('c-g3','A Group 1 metal forms which ion?',['1+','1−','2+'],0,'Losing one outer electron gives a +1 charge.','group1')],skills:['WS1.2','MS3a']},
{id:'halogens',title:'Group 7: halogens',short:'One electron to gain',refs:['1.2.6'],minutes:18,widget:'halogens',big:'Halogen reactivity decreases down Group 7. A more reactive halogen displaces a less reactive one from its salt solution.',learn:[
card('A different family.','Fluorine (F), chlorine (Cl), bromine (Br) and iodine (I) are halogens; astatine (At) is below iodine. Halogens have seven outer electrons and exist as diatomic molecules. At room temperature chlorine is a pale green gas, bromine is a red-brown liquid and iodine is a grey solid. Melting and boiling points increase down the group as relative molecular mass increases.','oxygen'),
card('Gain or share.','With metals, chlorine, bromine and iodine form ionic metal halides: 2Na + Cl₂ → 2NaCl. With non-metals they form covalent compounds: H₂ + Cl₂ → 2HCl. A halogen atom can gain one electron to form a 1− halide ion. Further down the group, shielding and greater distance make attraction for an incoming electron weaker, so reactivity decreases.','atom:Cl'),
card('Predict displacement.','Chlorine is more reactive than bromine, which is more reactive than iodine. Cl₂ + 2KBr → 2KCl + Br₂: chlorine displaces bromine from potassium bromide solution. Bromine cannot displace chlorine from a chloride. A change in colour can be evidence of a reaction, but identify the substances rather than assuming every colour change is displacement.','mixture')],
practice:[Q('p-h1','Can chlorine displace iodine from potassium iodide?',['Yes','No'],0,'Chlorine is more reactive than iodine.','displacement'),Q('p-h2','Which halogen has the highest boiling point: Cl₂, Br₂ or I₂?',['Cl₂','Br₂','I₂'],2,'Boiling point increases down the group.','group7')],
check:[Q('c-h1','Which has seven outer electrons?',['A chlorine atom','A sodium atom','A helium atom'],0,'Chlorine is in Group 7.','group7'),Q('c-h2','Bromine is added to potassium chloride solution. What happens?',['It displaces chlorine','No displacement occurs','Potassium becomes bromine'],1,'Bromine is less reactive than chlorine.','displacement'),Q('c-h3','Why does reactivity decrease down Group 7?',['An incoming electron is attracted less strongly','Outer electrons get closer to the nucleus','Atoms lose all their neutrons'],0,'More shells increase distance and shielding.','group7')],skills:['WS1.2','AT6']},
{id:'transition',title:'Transition metals',short:'A different kind of metal',refs:['1.3.1','1.3.2'],minutes:15,separate:true,widget:'transition',big:'Compared with Group 1, transition metals are generally harder, stronger, denser, higher-melting and less reactive.',learn:[
card('Compare the evidence.','Chromium, manganese, iron, cobalt, nickel and copper are examples of transition elements studied here. Compared with Group 1 metals, they generally have higher melting points and densities and are stronger and harder. They react less readily with oxygen, water and halogens. These are general patterns: compare specific data when it is supplied.','atom:Mg'),
card('More than one charge.','Many transition metals form ions with different charges. Iron can form Fe²⁺ and Fe³⁺. Their compounds are often coloured: copper(II) sulfate is blue and potassium manganate(VII) is purple. The colour belongs to a particular compound or ion in its environment, not a universal colour for every compound of that metal.','water'),
card('Useful catalysts.','Many transition metals and their compounds are catalysts. Iron is used in the Haber process, nickel in hydrogenation, and manganese dioxide in the decomposition of hydrogen peroxide. A catalyst increases reaction rate without being used up overall. Its usefulness does not depend on being as reactive as an alkali metal.','carbon')],
practice:[Q('p-tr1','Compared with sodium, iron is generally…',['Harder and denser','Softer and less dense','A non-metal'],0,'Iron exemplifies the stronger, harder, denser transition-metal pattern.','transition'),Q('p-tr2','Which pair illustrates variable ion charge?',['Fe²⁺ and Fe³⁺','Na⁺ and Na⁺','Cl⁻ and Cl⁻'],0,'The same metal forms ions with two different charges.','transition')],
check:[Q('c-tr1','Which is a typical use of a transition metal?',['Catalysing a reaction','Replacing all gases in Group 0','Making every compound colourless'],0,'Many transition metals and their compounds are useful catalysts.','transition'),Q('c-tr2','Compared with lithium, copper reacts with cold water…',['Less readily','More violently','With identical reactivity'],0,'Transition metals are generally less reactive than Group 1.','transition'),Q('c-tr3','Which statement is most accurate?',['Many transition-metal compounds are coloured','All compounds of each transition metal have the same colour','All transition metals form only 1+ ions'],0,'Different compounds can have different colours and ions can have different charges.','transition')],skills:['WS3.5','WS1.2']}
];
