const modelLesson=lessons.find(l=>l.id==='models');modelLesson.check.push(question('atomic.evidence.neutron','Whose work provided evidence for neutrons?',['James Chadwick','Niels Bohr','Dmitri Mendeleev'],0,'Chadwick’s experiments provided evidence for neutrons in the nucleus.','atomic-evidence'),question('atomic.evidence.models','What distinguishes the nuclear model from plum pudding?',['Positive charge and most mass are concentrated in a tiny nucleus','Positive charge is spread evenly through the atom','The nuclear model has no positive charge'],0,'Large alpha-particle deflections require concentrated positive charge and mass.','atomic-evidence'));
